  newsTitle: "What is new in RedGiant {version}",
  newsOk: "Got it",
  news330Canvas: "Any file in the Canvas",
  news330CanvasText:
    "Ask an agent to show you a file and it opens in the Canvas beside the chat: videos and sounds with their player, PDFs, Word, Excel and PowerPoint files laid out as they print, sheets also as a table to sort and filter, 3D models to turn and zoom, archives, fonts, code, data. Everything stays on your computer.",
  news330Convert: "Closed files become open ones, layout included",
  news330ConvertText:
    "Agents work only on open formats: graphics and documents from closed programs are converted beside the original, which stays as it is, without losing the layout. An IDML becomes a Scribus file (or a drawing with every frame in place), Sketch becomes vector drawings, a PSD keeps its layers. What a copy cannot keep is said plainly; for InDesign and Affinity files RedGiant tells you what to export, and opens the app if you have it. The programs needed are downloaded the first time, with their bar.",
  news330Blender: "Blender for the agents",
  news330BlenderText:
    "Agents can build and change 3D models with Blender, convert them to glTF and render pictures or a turntable video, shown in the Canvas. Blender is downloaded the first time it is needed.",
  news330Tools: "The Tools page",
  news330ToolsText:
    "In Settings > Tools you see every tool the agents have, what it does and how much it weighs on each request. Switch one off for everyone or agent by agent: it counts from the next conversation. The tools some features cannot do without stay on, and say why.",
  news323Keychain: "The Keychain",
  news323KeychainText:
    "A safe place for your passwords and keys, encrypted and never in a project or on git. Agents use a credential by name: the value is added only on the way out, only towards the sites you allow, and never shown to them or written in chat. Search, categories, a password generator, import from Bitwarden, 1Password and the browsers.",
  news323Memory: "A memory shared by every agent",
  news323MemoryText:
    "What RedGiant knows about you, learned by itself while you talk and used by every agent, as in the apps of Claude and ChatGPT. You see, change, delete or forget for ever each memory. Each agent keeps a memory of its own too.",
  news323Automations: "Automations without limits, and magic ones",
  news323AutomationsText:
    "New triggers (a message on a chat, files changing, another automation ending), conditions like working hours, approval, a budget and retries. With «Magic automation» you describe what you want and God builds it with you; it starts only when you approve it. As many mailboxes as you like, by category.",
  news323More: "And more",
  news323MoreText:
    "The language the agents speak is chosen apart from the interface's, among 76. Every agent's instructions are visible and editable. Agents open in a window; services show their own logos.",
  news321Settings: "Settings in the setup's style",
  news321SettingsText:
    "Every page of Settings now looks like the setup: big titles, tiles lit when something is on, details in windows in the middle, sections in five groups and, on a phone, a bar that opens their list. Nothing was taken away.",
  news321Linux: "Next layer ahead on Linux too",
  news321LinuxText:
    "The experimental «Next layer ahead» switch of SSD stream now works on Linux with an NVIDIA card too, with an engine image of its own downloaded only when you turn it on.",
  news32Setup: "The setup, one thing at a time",
  news32SetupText:
    "The configuration is new: one question per page, big buttons, a counter that opens the list of steps, details in windows in the middle, and a layout of its own on the phone. Each choice shows what it really sets.",
  news32Sources: "Sources inside the answer",
  news32SourcesText:
    "When an answer comes from the web, its sources are small links right in the text, named after their site, and the list underneath is drawn small.",
  news32Models: "Model details in a window",
  news32ModelsText:
    "The details of a local model open in a window above everything, no longer in a panel on the side.",
  news32Stream: "SSD stream: two experimental switches",
  news32StreamText:
    "Next to SSD stream: «Big chunks» reads long messages in bigger passes, and «Next layer ahead» (Windows, NVIDIA) uses our own llama.cpp that copies the next experts while the card computes: up to 1.7 times faster reading on an RTX 4080 Super. With an NVIDIA card on Windows, advice on the driver's sysmem fallback, which slows reading down.",
  subsSharedLogin:
    "{name} is already signed in on this computer: RedGiant uses that sign-in as it is, no need to sign in again.",
  subsProgramSystem: "{name} is already installed on this computer: RedGiant uses it.",
  subsProgramDownload:
    "{name} is downloaded when you switch this on (once, a few hundred MB, with its bar in the corner).",
  subsUseShared: "Use the sign-in already here",
  instructionsTitle: "Instructions for every agent",
  backupModelTitle: "Backup model for tasks",
  backupModelHint:
    "When an agent gives up on a task (an error, the budget, or no check that the result is right), this model tries it once more in a new conversation, knowing what the first attempt did. Better if it is from another provider.",
  backupModelNone: "None: a task given up on stays so",
  instructionsHint:
    "What every agent should know or do, whoever it is: how you like answers, your conventions, things to avoid. They are added to each agent's own instructions (those are in each agent's card under Agents).",
  instructionsPlaceholder:
    "For example: answer in Italian; code and comments in English; never push without asking.",
  instructionsSaved: "Saved: conversations started from now on follow them.",
  sentWhileWorking: "Sent while the agent works: it reads it as soon as it can",
