  by: "da",
  scopePlatform: "piattaforma",
  telegram: "Telegram",
  newsTitle: "Le novità di RedGiant {version}",
  newsOk: "Ho capito",
  news330Canvas: "Qualsiasi file nel Canvas",
  news330CanvasText:
    "Chiedi a un agente di mostrarti un file e si apre nel Canvas accanto alla chat: video e audio con il loro lettore, PDF, file di Word, Excel e PowerPoint impaginati come in stampa, fogli anche come tabella da ordinare e filtrare, modelli 3D da girare e ingrandire, archivi, font, codice, dati. Tutto resta sul tuo computer.",
  news330Convert: "I file chiusi diventano aperti, impaginazione compresa",
  news330ConvertText:
    "Gli agenti lavorano solo su formati aperti: grafica e documenti di programmi chiusi vengono convertiti accanto all'originale, che resta com'è, senza perdere l'impaginazione. Un IDML diventa un file di Scribus (o un disegno con ogni cornice al suo posto), Sketch diventa disegni vettoriali, un PSD tiene i suoi livelli. Quello che una copia non può tenere è detto chiaro; per i file di InDesign e Affinity RedGiant ti dice cosa esportare, e apre il programma se ce l'hai. I programmi che servono si scaricano la prima volta, con la loro barra.",
  news330Blender: "Blender per gli agenti",
  news330BlenderText:
    "Gli agenti possono costruire e cambiare modelli 3D con Blender, convertirli in glTF e fare immagini o un video che gira attorno al modello, mostrati nel Canvas. Blender si scarica la prima volta che serve.",
  news330Tools: "La pagina degli Strumenti",
  news330ToolsText:
    "In Impostazioni > Strumenti vedi tutti gli strumenti degli agenti, cosa fanno e quanto pesano su ogni richiesta. Spegnine uno per tutti o agente per agente: vale dalla conversazione dopo. Gli strumenti di cui alcune funzioni non possono fare a meno restano accesi, e dicono perché.",
  news323Keychain: "Il Portachiavi",
  news323KeychainText:
    "Un posto sicuro per password e chiavi, cifrato e mai dentro un progetto o su git. Gli agenti usano una credenziale per nome: il valore viene aggiunto solo all'uscita, solo verso i siti che permetti, e non lo vedono mai né lo scrivono in chat. Ricerca, categorie, generatore di password, importazione da Bitwarden, 1Password e dai browser.",
  news323Memory: "Una memoria condivisa da tutti gli agenti",
  news323MemoryText:
    "Quello che RedGiant sa di te, imparato da solo mentre parli e usato da tutti gli agenti, come nelle app di Claude e ChatGPT. Ogni ricordo lo vedi, lo cambi, lo cancelli o lo dimentichi per sempre. Ogni agente ha anche una memoria tutta sua.",
  news323Automations: "Automazioni senza limiti, e quelle magiche",
  news323AutomationsText:
    "Inneschi nuovi (un messaggio su una chat, file che cambiano, un'altra automazione che finisce), condizioni come l'orario di lavoro, approvazione, limite di spesa e nuovi tentativi. Con «Automazione magica» descrivi cosa vuoi e God la costruisce con te; parte solo quando la approvi. Caselle email quante vuoi, per categoria.",
  news323More: "E poi",
  news323MoreText:
    "La lingua in cui parlano gli agenti si sceglie a parte da quella dell'interfaccia, tra 76. Le istruzioni di ogni agente si vedono e si cambiano. Gli agenti si aprono in una finestra; i servizi hanno i loro loghi.",
  news321Settings: "Le Impostazioni nello stile della configurazione",
  news321SettingsText:
    "Tutte le pagine delle Impostazioni ora sono come la configurazione: titoli grandi, riquadri accesi quando qualcosa è attivo, dettagli in finestre al centro, sezioni in cinque gruppi e, sul telefono, una barra che ne apre l'elenco. Non è stato tolto niente.",
  news321Linux: "Strato dopo in anticipo anche su Linux",
  news321LinuxText:
    "L'interruttore sperimentale «Strato dopo in anticipo» di SSD stream ora funziona anche su Linux con una scheda NVIDIA, con un'immagine del motore tutta sua scaricata solo quando lo accendi.",
  news32Setup: "La configurazione, una cosa alla volta",
  news32SetupText:
    "La configurazione è nuova: una domanda per pagina, pulsanti grandi, un contatore che apre l'elenco dei passi, i dettagli in finestre al centro e una versione tutta sua sul telefono. Ogni scelta mostra cosa imposta davvero.",
  news32Sources: "Le fonti dentro la risposta",
  news32SourcesText:
    "Quando una risposta viene dal web, le fonti sono piccoli link direttamente nel testo, con il nome del sito, e l'elenco sotto è scritto in piccolo.",
  news32Models: "I dettagli dei modelli in una finestra",
  news32ModelsText:
    "I dettagli di un modello locale si aprono in una finestra sopra a tutto, non più in un pannello di lato.",
  news32Stream: "SSD stream: due interruttori sperimentali",
  news32StreamText:
    "Accanto a SSD stream: «Blocchi grandi» legge i messaggi lunghi a blocchi più grandi, e «Strato dopo in anticipo» (Windows, NVIDIA) usa un llama.cpp nostro che copia gli esperti successivi mentre la scheda calcola: lettura fino a 1,7 volte più veloce su una RTX 4080 Super. Con una scheda NVIDIA su Windows, un consiglio sul Sysmem Fallback del driver, che rallenta la lettura.",
  subsSharedLogin:
    "{name} è già collegato su questo computer: RedGiant usa quell'accesso così com'è, senza rifarlo.",
  subsProgramSystem: "{name} è già installato su questo computer: RedGiant usa quello.",
  subsProgramDownload:
    "{name} viene scaricato quando lo attivi (una volta sola, qualche centinaio di MB, con la barra nell'angolo).",
  subsUseShared: "Usa l'accesso già presente",
  instructionsTitle: "Istruzioni per tutti gli agenti",
  backupModelTitle: "Modello di riserva per i task",
  backupModelHint:
    "Quando un agente rinuncia a un task (un errore, il budget, o nessuna verifica che il risultato sia giusto), questo modello lo riprova una volta in una conversazione nuova, sapendo cosa ha fatto il primo tentativo. Meglio se è di un altro fornitore.",
  backupModelNone: "Nessuno: un task abbandonato resta tale",
  instructionsHint:
    "Quello che ogni agente deve sapere o fare, chiunque sia: come vuoi le risposte, le tue convenzioni, cosa evitare. Si aggiungono alle istruzioni proprie di ciascun agente (quelle sono nella sua scheda, in Agenti).",
  instructionsPlaceholder:
    "Per esempio: rispondi in italiano; codice e commenti in inglese; mai fare push senza chiedere.",
  instructionsSaved: "Salvate: le seguono le conversazioni che cominciano da adesso.",
  sentWhileWorking: "Mandato mentre l'agente lavora: lo legge appena può",
  voiceLocal: "Sul computer (whisper.cpp)",
  voiceLocalHint:
    "Nessun account e niente esce da questo computer. RedGiant scarica una volta whisper.cpp e un modello multilingue (circa 560 MB, con la barra nell'angolo) e li fa girare lui.",
  job_download_whisper: "Scarico whisper.cpp per i vocali (una volta sola)",
  job_download_ffmpeg: "Scarico ffmpeg, per leggere ogni tipo di vocale (una volta sola)",
