export const dictionaries: Record<Lang, Record<Key, string>> = { en, it };

const initial = (): Lang => {
  const saved = typeof localStorage !== "undefined" ? localStorage.getItem("rg.lang") : null;
  if (saved === "it" || saved === "en") return saved;
  return typeof navigator !== "undefined" && navigator.language.startsWith("it") ? "it" : "en";
};

export const lang = signal<Lang>(initial());

export function setLang(l: Lang): void {
  lang.value = l;
  localStorage.setItem("rg.lang", l);
}

/** A danger of the permission policy in plain words: its name and a line with an example. */
export const danger = (id: string) => dangerWords(lang.value, id);

/** Translates a key; `{name}` placeholders are filled from `vars`. */
export function t(key: Key, vars: Record<string, string> = {}): string {
  return dictionaries[lang.value][key].replace(/\{(\w+)\}/g, (_, k: string) => vars[k] ?? `{${k}}`);
}

/** Translates a key made at run time (a job's step, an error code); undefined if there is none. */
export function tOptional(key: string, vars: Record<string, string> = {}): string | undefined {
  return key in dictionaries.en ? t(key as Key, vars) : undefined;
}

/** Descriptions RedGiant writes itself (the Chat's, the setup's, the wizard's roles), whichever
 * language they were written in, are shown in the interface's language (2026-11-07). */
const BUILT_IN_ROLES: Key[] = [
  "chatAgentRole",
  "wzGodRole",
  "wzDemiRole",
  "agentRole_coder",
  "agentRole_reviewer",
  "agentRole_researcher",
  "agentRole_writer",
  "agentRole_tester",
];
export function roleText(role: string | undefined): string | undefined {
  if (!role) return role;
  const key = BUILT_IN_ROLES.find(
    (k) => role === dictionaries.en[k] || role === dictionaries.it[k],
  );
  return key ? t(key) : role;
}
